p='src/ctx.c'
s=open(p).read()
s=s.replace('''/* How much of one turn is printed unless --full is given. */
#define TURN_SHOW 8000

/* ctx turn ID [BEFORE [AFTER]] [--full] */
static int cmd_turn(int argc, char **argv) {
  int full = 0, nums[3] = {0, 0, 0}, have = 0;''','''/* How much of one turn is printed unless --full or --max-bytes is given. */
#define TURN_SHOW 8000

/* ctx turn ID [BEFORE [AFTER]] [--full] [--max-bytes N] */
static int cmd_turn(int argc, char **argv) {
  int full = 0, nums[3] = {0, 0, 0}, have = 0;
  size_t turn_show = TURN_SHOW;''')
s=s.replace('''    if (!strcmp(argv[i], "--full")) full = 1;
    else if (!have && argv[i][strspn''','''    if (!strcmp(argv[i], "--full")) full = 1;
    else if (!strcmp(argv[i], "--max-bytes") && i + 1 < argc) {
      char *end;
      long v = strtol(argv[++i], &end, 10);
      if (*end || end == argv[i] || v < 1) die("--max-bytes must be at least 1");
      turn_show = (size_t)v;
    }
    else if (!have && argv[i][strspn''')
s=s.replace('die("usage: ctx turn ID [BEFORE [AFTER]] [--full]")','die("usage: ctx turn ID [BEFORE [AFTER]] [--full] [--max-bytes N]")')
s=s.replace('''    if (!full && n > TURN_SHOW) {
      show = TURN_SHOW;''','''    if (!full && n > turn_show) {
      show = turn_show;''')
s=s.replace('''"       ctx turn ID [BEFORE [AFTER]] [--full]\\n"''','''"       ctx turn ID [BEFORE [AFTER]] [--full] [--max-bytes N]\\n"''')
open(p,'w').write(s)
p='docs/howto.md'
s=open(p).read()
s=s.replace('''ctx turn ID 0 0 --full           # without trimming a long turn
''','''ctx turn ID 0 0 --full           # without trimming a long turn
ctx turn ID --max-bytes 2000     # trim a long turn at 2000 bytes instead of 8000
''',1)
open(p,'w').write(s)
p='test/run.sh'
s=open(p).read()
s=s.replace('''[ "$("$CTX" turn "$ID" --full | wc -c)" -gt 20000 ] || fail "--full shows it all"
''','''[ "$("$CTX" turn "$ID" --full | wc -c)" -gt 20000 ] || fail "--full shows it all"
"$CTX" turn "$ID" --max-bytes 100 | grep -q 'more bytes; use --full' || fail "--max-bytes cuts a turn"
[ "$("$CTX" turn "$ID" --max-bytes 100 | wc -c)" -lt 400 ] || fail "--max-bytes 100 shows about 100 bytes"
[ "$("$CTX" turn "$ID" --max-bytes 15000 | wc -c)" -gt 15000 ] || fail "--max-bytes can show more than the default"
if "$CTX" turn "$ID" --max-bytes 0 2>/dev/null; then fail "--max-bytes 0 is refused"; fi
if "$CTX" turn "$ID" --max-bytes abc 2>/dev/null; then fail "--max-bytes needs a number"; fi
''')
open(p,'w').write(s)
EOF
git diff --stat; make test 2>&1 | tail -15

